parameters.query:
SELECT json_agg(
    json_build_object(
        'id', id,
        'name', name
    )
    ORDER BY id
) AS symptoms
FROM symptoms;

parameters.jsCode:
const dbSymptoms = $('Symptom Query').first().json.symptoms;

const dbMap = new Map(
  dbSymptoms.map(s => [s.name.toLowerCase().trim(), s])
);

const symptoms = $json.symptoms ?? [];

const corrected = symptoms
  .map(s => {
    const match = dbMap.get(s.symptom.toLowerCase().trim());

    if (!match) {
      return null;
    }

    return {
      symptom_id: match.id,
      symptom: match.name,
      evidence: s.evidence,
      certainty: s.certainty
    };
  })
  .filter(Boolean);

return [{
  json: {
    symptoms: corrected
  }
}];

