const content = $json.choices?.[0]?.message?.content;

if (!content) {
  return [
    {
      json: {
        error: "EmergencyCheck returned no content"
      }
    }
  ];
}

try {
  let cleaned = String(content).trim();

  // Entfernt ```json ... ```
  cleaned = cleaned
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  const result = JSON.parse(cleaned);

  return [
    {
      json: result
    }
  ];

} catch (error) {
  return [
    {
      json: {
        error: "EmergencyCheck returned invalid JSON",
        raw_content: content,
        parse_error: error instanceof Error
          ? error.message
          : String(error)
      }
    }
  ];
}

